from pathlib import Path
import ast,datetime,hashlib,importlib.util,json,statistics,sys
ROOT=Path(__file__).resolve().parents[3];OUT=ROOT/'experiments/R2_open';sys.path.insert(0,str(ROOT))
def read(p):return json.loads(p.read_text())
def save(p,v):p.write_text(json.dumps(v,ensure_ascii=False,indent=2))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()

def main():
 # R5 contains two development builds; both are retained and counted.
 names=['r5_development','r5_corrected_development','r5_final_development'];builds=[];fields=['cleared_count','source_count','complete','exit_reason','error','average_clear_time_s','total_virtual_time_s','distance_m','requests','clear_failures']
 for name in names:
  folder=OUT/'results'/name;summary=read(folder/'summary.json');parent=read(folder/'parent_rows.json');idx={x['case_id']:x for x in parent};assert len(parent)==384
  variants=[]
  for variant in ('parent','multi_cost','direct'):
   rows=read(folder/(variant+'_rows.json'));assert len(rows)==384 and len({x['case_id'] for x in rows})==384 and all(x['complete'] and not x['error'] and x['exit_reason']=='user_exit' for x in rows)
   assert all(x[k]==idx[x['case_id']][k] for x in rows if x['mode']==4 for k in fields)
   q3=[x for x in rows if x['mode']==3]
   variants.append(dict(name=variant,q3=statistics.mean(x['average_clear_time_s'] for x in q3),q4=statistics.mean(x['average_clear_time_s'] for x in rows if x['mode']==4),mean_requests=statistics.mean(x['requests'] for x in q3),mean_distance_m=statistics.mean(x['distance_m'] for x in q3),mean_runtime_s=statistics.mean(x['runtime_s'] for x in q3),mean_sharing_spent_s=statistics.mean(x['sharing_spent_s'] for x in q3),clear_failures=sum(x['clear_failures'] for x in q3),opportunity_measures=sum(x['counters'].get('opportunity_measures',0) for x in q3),geometry_checks=sum(x['geometry_checks'] for x in rows),rows_sha256=sha(folder/(variant+'_rows.json'))))
  builds.append(dict(name=name,variants=variants,budget=read(folder/'budget.json'),cases_sha256=sha(folder/'cases.json')))
 assert len({b['cases_sha256'] for b in builds})==1
 corrected=builds[-1]['variants'];assert min(corrected,key=lambda x:x['q3'])['name']=='parent'
 correction=read(OUT/'research/r5_code_correction.json');assert sha(OUT/'snapshots/r5_initial_graph.py')==correction['old_sha256'];assert sha(OUT/'snapshots/r5_graph_corrected.py')==correction['new_sha256'];cache_correction=read(OUT/'research/r5_cache_correction.json');assert sha(OUT/'snapshots/r5_development.py')==cache_correction['new_sha256']
 r5=dict(id='R2_open_R5',kind='development_only',status='rejected_development',selected='R2_open_R4',builds=builds,total_policy_executions=sum(b['budget']['actual_runs'] for b in builds),unique_cases=384,code_correction=correction,cache_correction=cache_correction,graph_invariant_checks=read(OUT/'results/r5_graph_checks.json')['passed'],candidate_for_exposed=None,reason='Both multi-position cost and corrected graph-progress gate increase complete Q3 development mean; no structural breakthrough. Preserve R4 and stop per user near-convergence instruction.',boundary='This rejects these concrete planning surrogates and finite hypotheses, not the DIRECt theorem or all future decision-aware planning.')
 save(OUT/'research/r5_selection.json',r5)
 t='# R5 开发否证与修复记录\n\nR5没有冻结新的暴露回归候选，保留R4。初稿、图修复版、图加缓存修复版各384例×3配置共3456次执行，全部全清；修正版重用同一开发案例，不算新独立重复验证。\n\n|构建|配置|Q3秒/源|Q4秒/源|Q3请求/局|Q3距离米/局|Q3平均运行秒|\n|---|---|---:|---:|---:|---:|---:|\n'
 for b in builds:
  for x in b['variants']:t+=f"|{b['name']}|{x['name']}|{x['q3']:.12f}|{x['q4']:.12f}|{x['mean_requests']:.6f}|{x['mean_distance_m']:.6f}|{x['mean_runtime_s']:.6f}|\n"
 t+='\n修正：某决策图原始边权为零意味着有限假说已经属于同一有效决策区，必须触发退化回费用门控。原稿错误地略过该图后可能保留其他图的剩余歧义。修复前后的源码、SHA、全部原始行和真实调用数量均保留；连续真实P从未因此变化。111个独立有限图不变量检查通过，检查涵盖离散目标等价、三分离位置的2/3边切分、包含单调与空剩余假说回退。\n\n最终数值见上表，多位置费用与图进展代理均未优于父法。两者少走了一点路，却增加请求并提高本机推理开销。不能把此具体小假说/误差一致性/费用换算方案的负结果写成DIRECt理论失效；本题未满足其完整离散先验和确定观测前提。另补充正观测历史到假说缓存键，避免相同P但不同接收半径条件的状态复用；确定性状态检查通过。没有R5 quick/full/4800，也没有把重复开发称作最终留出。\n'
 (OUT/'research/r5_results.md').write_text(t)
 path=read(OUT/'optimization_path.json');record=next(x for x in path['rounds'] if x['id']=='R2_open_R5');record.update(status='rejected_development',kind='development_only',after_development=r5,decision='Retain R4 and freeze study after user permits near-convergence closure.',next='Root-only fresh holdout; no parameter updates after seeing it.');path['status']='closed_for_final_validation';save(OUT/'optimization_path.json',path)
 budget=read(OUT/'execution_budget.json');old_entry=budget['rounds'].pop('R5',None)
 if old_entry:
  for k in ('development_runs','development_unique_cases','total_policy_executions','geometry_assertions'):budget[k]-=old_entry[k]
 entry=dict(training_runs=0,development_runs=3456,development_unique_cases=384,development_seed_range=[42000052,42000067],quick_runs=0,full_runs=0,previous_final_runs=0,total_policy_executions=3456,geometry_assertions=sum(x['geometry_checks'] for b in builds for x in b['variants']),development_wall_s=sum(b['budget']['wall_s'] for b in builds),builds=3,graph_invariant_checks=111,reason_no_regression='No new variant beat parent on the registered development criterion; frozen R4 already has complete validation.')
 budget['rounds']['R5']=entry
 for k in ('development_runs','development_unique_cases','total_policy_executions','geometry_assertions'):budget[k]+=entry[k]
 budget['rounds_completed']=5;budget['frozen_rounds_started']=4;
 for key in ('development_wall_s','quick_wall_s','full_wall_s','previous_final_wall_s'):budget[key]=sum(r.get(key,0.) for r in budget['rounds'].values())
 budget['policy_execution_wall_sum_s']=sum(budget[k] for k in ('development_wall_s','quick_wall_s','full_wall_s','previous_final_wall_s'));budget['geometry_state_checks_include_repeated_development']=True;budget['finite_graph_invariant_checks']=111;budget['cache_invalidation_checks']=1;
 budget['development_seed_range']=[42000000,42000067];budget['synthetic_geometry_regions_total']=3000;budget['synthetic_geometry_assertions_total']=15000;budget['synthetic_geometry_seeds']=[42000999,42001999];budget['note']='All policy executions counted, including 120-case quick subsets and R5 corrected-build rerun on identical development cases. 5 studies, 4 frozen candidates, no R5 exposed run, zero new final cases.';save(OUT/'execution_budget.json',budget)
 seeds=read(OUT/'research/used_seeds.json');seeds['development_ranges']=sorted({tuple(v) for v in seeds['development_ranges']}|{(42000052,42000067)});seeds['known_seed_audit_reference']='research/known_seed_audit.json';seeds['final_sampling_must_exclude']=list(range(42000000,42000068))+seeds['geometry_only'];save(OUT/'research/used_seeds.json',seeds)
 # Independent raw-row identity and all 78 comparison cells for every freeze.
 import evaluate
 evaluate.verify();spec=importlib.util.spec_from_file_location('exposed_final_audit',ROOT/'experiments/20260911_stage3/evaluate_exposed.py');ev=importlib.util.module_from_spec(spec);spec.loader.exec_module(ev)
 baseline=read(ROOT/'experiments/20260911_stage3/baseline/expected_rows.json');audit_rounds=[];previous=baseline
 for r in range(1,5):
  folder=OUT/f'results/r{r}_exposed';rows=read(folder/'case_metrics.json');summary=read(folder/'summary.json');src=OUT/f'snapshots/r{r}_solver.py';assert sha(src)==summary['candidate_sha256'];assert len(rows)==4800==len({x['case_id'] for x in rows}) and all(ev.valid(x) for x in rows)
  cmp=ev.compare(rows,baseline);old=summary['comparisons_to_S0'];assert len(cmp)==len(old)==78
  for a,b in zip(cmp,old):
   for k,v in a.items():
    assert k in b and (abs(v-b[k])<1e-9 if isinstance(v,float) else v==b[k]),(r,k,v,b.get(k))
  q4={x['case_id']:x for x in baseline if x['mode']==4};assert all(x[k]==q4[x['case_id']][k] for x in rows if x['mode']==4 for k in fields)
  audit_rounds.append(dict(round=r,candidate_sha256=sha(src),rows_sha256=sha(folder/'case_metrics.json'),all_4800_complete=True,recomputed_cells=78,against_S0=[x for x in cmp if x['group']=='ALL'],against_previous=[x for x in ev.compare(rows,previous) if x['group']=='ALL'],q4_task_fields_equal=True))
  previous=rows
 final=OUT/'snapshots/r4_solver.py';tree=ast.parse(final.read_text());attrs=sorted({n.attr for n in ast.walk(tree) if isinstance(n,ast.Attribute) and isinstance(n.value,ast.Attribute) and n.value.attr=='env'});assert attrs==['clear','enter','exit','measure'];names={n.id for n in ast.walk(tree) if isinstance(n,ast.Name)};assert not names.intersection({'LocalEnv','Source','case_id','seed','scenario'})
 r1tree=ast.parse((OUT/'snapshots/r1_solver.py').read_text());di=lambda t:{n.name:ast.dump(n,include_attributes=False) for n in t.body if isinstance(n,(ast.ClassDef,ast.FunctionDef)) and n.name.startswith('_di_')};assert di(tree)==di(r1tree)
 finalaudit=dict(created_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),rounds=audit_rounds,final_candidate=str(final.resolve()),final_sha256=sha(final),deployment_dependencies={},runtime='Python >=3.10 standard library; validated 3.12.14; no external model/weight/data file',env_methods=attrs,q4_definitions_match_R1=True,final_geometry_bound_virtual_s=283091,frozen_v1_verified=True,rows_recomputed_only_no_new_policy_execution=True,total_policy_executions=budget['total_policy_executions'],r5_development_status='rejected',seed_manifest='research/used_seeds.json');save(OUT/'results/final_delivery_audit.json',finalaudit)
 best=read(OUT/'best.json');best.update(status='frozen for root fresh final validation',code_commit='6913faf',study_closed=True,last_study='R5 development-only rejected',no_further_tuning=True);save(OUT/'best.json',best)
 freeze=dict(schema_version=1,agent='R2_open',frozen_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),candidate='experiments/R2_open/snapshots/r4_solver.py',candidate_sha256=sha(final),candidate_code_commit='6913faf',mode3_component_best=True,mode4='S0 retained for isolation; use R3_open separately only after actual integration',deployment_dependencies={},external_runtime='Python standard library only',exposed_results='experiments/R2_open/results/r4_exposed',exposed_Q3=best['q3'],exposed_Q4=best['q4'],legal_complete_cases=4800,data_role='already exposed development regression',new_final_seen=False,final_seed_exclusions='experiments/R2_open/research/used_seeds.json',studies=5,frozen_candidates=4,total_actual_policy_executions=budget['total_policy_executions'],reason_for_freeze='User permits near-convergence closure; recent valid Q3 gains small, richer R5 hypotheses/graph increased cost without structural breakthrough.',evidence_boundary='Not proof of global optimum. No official Windows run. Root owns unseen final and no post-final retuning.');save(OUT/'FINAL_CANDIDATE.json',freeze)
 # Rewrite a coherent final report while all historical raw path records remain.
 finalcmp=audit_rounds[-1]['against_S0'];prevcomp=audit_rounds[-1]['against_previous'];r4audit=read(OUT/'results/r4_delivery_audit.json')
 report='''# R2_open 第三阶段研究报告（冻结）\n\n最终保留R4：第三问235.876945811892秒/源，较S0的238.426470616150降低1.0693128%。四次冻结候选都完成4800局已暴露回归；最终全清、正常退出、零异常，每题30970/30970源清除。第四问逐行保持S0 524.827143981088秒/源，用于隔离本路线第三问组件；R3_open另有更强第四问，须由主协调实际组合验证，不能把本文件当作最终共同求解器。\n\n源码：[r4_solver.py](snapshots/r4_solver.py)，SHA256 `d0bda0a51470eda3bd5f713be1552a004c7a73b8debcb333c323afd06d4c68f3`，源码提交`6913faf`。标准库自包含，无外部模型、权重、数据或coverage文件依赖。机器可读冻结入口：[FINAL_CANDIDATE.json](FINAL_CANDIDATE.json)。\n\n## 评价口径与证据\n\n每局官方式指标为T_i/n_i；此处题均值为(1/N)Σ(T_i/n_i)，每题合并N=2400、每批N=1200。30970是完整性源数分母，不把它误作上述未加权案例均值的权重。降幅=1−候选均值/S0均值。v1与previous_final都已经暴露；全部结果是本地合法构造场景，不是新的留出或官方成绩。没有筛选成功子集。最终独立审计重算4×78比较格、核对4800 ID、源码SHA和Q4任务字段，见[final_delivery_audit.json](results/final_delivery_audit.json)。\n\n## 全部研究轮次\n\n|轮|主要改变|Q3合并秒/源|较前轮变化|决定|\n|---|---|---:|---:|---|\n'''
 prev=238.42647061615037;descs=['A2可靠集合约束×B1协同路径','已到达点同址认证clear','DRD启发的补测动作费用代理','全部合法服务位置×后继路线']
 for r,x in enumerate(audit_rounds,1):
  q=next(y['candidate_mean_s_per_source'] for y in x['against_S0'] if y['mode']==3 and y['suite']=='combined');report+=f'|R{r}|{descs[r-1]}|{q:.12f}|{q-prev:+.12f}|保留|\n';prev=q
 report+='|R5|多位置费用/DIRECt启发连续进展|仅开发；未胜R4|不适用|保留R4，未进暴露回归|\n\n完整实验前记录、父版本、配置、选择依据与所有原始结果见[optimization_path.json](optimization_path.json)、[optimization_path.md](optimization_path.md)。R1–R4逐轮完整结果分别在research/r1_results.md至r4_results.md；R5初稿、两项修复和全部3456执行见[研究记录](research/r5_results.md)。\n\n## 最终两批结果与退步边界\n\n|批次|题|S0|R4|变化秒/源|快/同/慢|\n|---|---|---:|---:|---:|---|\n'
 for x in finalcmp:report+=f"|{x['suite']}|Q{x['mode']}|{x['baseline_mean_s_per_source']:.9f}|{x['candidate_mean_s_per_source']:.9f}|{x['delta_s_per_source']:+.9f}|{x['faster']}/{x['equal']}/{x['slower']}|\n"
 report+='\nR4较S0的Q3单局快1624、同0、慢776；origin_cluster在v1和previous_final分别退步0.650730与1.077471秒/源。最大单局退步51.1910495秒/源，位于previous_final minimum_radius；最终最差局375.1605581秒/源。全部48分批场景、全部776条单局退步和每批最差局均已保留，[完整表](research/r4_results.md)、[原始退步](results/r4_case_regressions.json)。稳定改善的是题均值，不能称每局或每场景都改善。\n\n## 关键负结果与启发\n\n- R2把A2主动第二测点直接加入已有协同，在独立开发中少走20.337米/局，却多3次请求、增加1.253634秒/源；只保留同址认证的小收益。\n- R3只在预测一步即可认证clear时补测，开发退步18.423851秒/源；关闭补测退步33.130044。费用代理有收益，但这些对照只能支持保留中间信息可能重要的机制假设，不能断言论文已证明本题因果。\n- R4全合法服务区域的最近进入点开发略退步；考虑后继路线才有开发及完整回归收益，不能把两个父组件历史降幅相加。\n- R5同一多位置假说的费用和DIRECt启发图进展均未胜单中心父法。最终修正版仍未优于父法，推理更重，精确逐版数值见R5表。最初图退化情形处理问题被修复，三次开发全部留档，不把修复重跑视作新独立验证。拒绝的是这些具体迁移与先验/价格模型，并非DIRECt原定理。\n\n## 文献与阅读深度\n\n940个历史文件全量解析、旧48轮原始指标重算；所有字节解析不等于逐轨迹人工复盘。阅读边界、每文件SHA/行数见[reading_coverage.json](reading_coverage.json)。本轮新增原文：Javdani等2014 DRD第3/8页、Chen等2015 VOI第2–5页；详细来源/未读范围见[literature.json](literature.json)。DRD用于R3的任务费用门控，DIRECt用于R5开发否证。R2同址clear在收到文献前已实施，不伪写为文献催生。没有跨假设搬用HEC或自适应次模近似保证。\n\n## 可靠性与开销\n\n部署只用enter/measure/clear/exit；假想观测不更新真实P。正负/失败约束为保守外包；真正clear由全部顶点距离≤20或父认证支持。所有发现、有限格点光学兜底与退出证书保留，统一虚拟上界283091秒<100小时。R4增加的圆弧搜索有限、超过32顶点退回原点位；固定状态路线代理不劣，整体在线收益由真实执行验证。证明分别见research/r1_reliability.md至r4_reliability.md。HTTP、并发、重试未改，未运行官方Windows。\n\n'''
 report+=f"累计{budget['total_policy_executions']}次实际策略执行：开发{budget['development_runs']}（{budget['development_unique_cases']}个不同合法案例，含R5重复构建），quick{budget['quick_runs']}，full-v1 {budget['full_runs']}，previous_final {budget['previous_final_runs']}。没有训练拟合模型、没有新最终样本。另有3000合成几何区域/15000凸组合或包含性质检查、111有限图不变量检查。每次解释器/费用账本见[execution_budget.json](execution_budget.json)。这些次数不是独立统计样本数，不包含阅读、设计、排队和提交耗时。\n\n"
 report+='## 近收敛判断与后续边界\n\n此次收束是用户允许“迭代接近收敛就可以收尾”后的研究决策，不是预设轮数或连续失败规则。R2–R4的Q3增量分别只有0.020917、0.453470、0.175713秒/源；更复杂的R5既没有结构性突破，还增加开发均值与计算开销。当前范围内继续扩大模型/参数的收益证据不足，因此冻结R4，停止新路线和调参。这不证明全局最优。主协调将用新的2400局留出实际运行S0与两方冻结候选；本研究尚未见该数据，之后不根据其结果修改或重新挑选组合。\n'
